def main():
 source=json.loads((DOC/'integration/opsnext-translation-source-20261102.json').read_text())['items']
 for locale,rows in [('zh-CN',CN),('zh-TW',TW)]:
  assert len(rows)==len(source)==15
  items={}
  for (qid,q),(stem,options,objective,explanation,reasons) in zip(source.items(),rows):
   assert len(options)==len(reasons)==4 and len(set(options))==4
